"""`mac time` — generated by tools/gen_groups.py from local-mac's time__* handlers. Do not edit."""
import argparse

from mac.groups._backend import call, given


def register(registry):
    @registry.verb("time", "now", mode="read",
                   desc='get the current time in IST')
    def time_now(ns):
        return call('time', 'now')

    def time_alarm_args(p):
        p.add_argument('time')
        p.add_argument('--label', default=argparse.SUPPRESS)
        p.add_argument('--reminder', default=argparse.SUPPRESS, action="store_true")

    @registry.verb("time", "alarm", mode="write",
                   desc='set an alarm at HH:MM (24h). Optionally also creates an Apple Reminder', args=time_alarm_args)
    def time_alarm(ns):
        return call('time', 'alarm', **given(ns, ('time', 'label', 'reminder')))

    def time_wait_args(p):
        p.add_argument('minutes', type=float)
        p.add_argument('--label', default=argparse.SUPPRESS)

    @registry.verb("time", "wait", mode="write",
                   desc='start a countdown timer for N minutes. Fires a macOS notification when done', args=time_wait_args)
    def time_wait(ns):
        return call('time', 'wait', **given(ns, ('minutes', 'label')))

    def time_cancel_args(p):
        p.add_argument('pid', type=int)

    @registry.verb("time", "cancel", mode="write",
                   desc='cancel a wait/alarm timer by the pid it reported. Stops its whole process group', args=time_cancel_args)
    def time_cancel(ns):
        return call('time', 'cancel', **given(ns, ('pid',)))

    def time_play_sound_args(p):
        p.add_argument('seconds', type=float)
        p.add_argument('--sound', default=argparse.SUPPRESS)

    @registry.verb("time", "play_sound", mode="write",
                   desc='play a macOS system sound repeatedly for N seconds', args=time_play_sound_args)
    def time_play_sound(ns):
        return call('time', 'play_sound', **given(ns, ('seconds', 'sound')))
